// Poll result written by WF2 into qa_runs (kind=verification).
const MAX_POLLS = 18; // 18 x 5 min = 90 min
const ctx = $('Wait for WF2 Result').last().json;
const row = $input.all().map((i) => i.json).find((r) => r && r.id !== undefined) || {};
const polls = (ctx.polls || 0) + 1;
const outcome = row.status === 'passed' ? 'pass' : row.status === 'failed' ? 'fail' : polls >= MAX_POLLS ? 'timeout' : 'pending';
const cfg = $('Config').first().json;
const run_url = row.run_id ? `https://github.com/${cfg.GITHUB_OWNER}/${cfg.GITHUB_REPO}/actions/runs/${row.run_id}` : '';
return [{ json: { ...ctx, polls, outcome, run_id: row.run_id || '', run_url, conclusion: row.conclusion || '' } }];

// Verification decision + Jira comment (fix-verification skill template). Never Closed: PASS -> Verified, FAIL -> Reopened.
const ctx = $input.first().json;
const pass = ctx.outcome === 'pass';
const today = $now.setZone('Asia/Karachi').toFormat('yyyy-MM-dd');
const comment = [
  `Verification — ${pass ? 'PASS' : 'FAIL'}`,
  `Build: ${ctx.plan.build} | Env: QA | Browser(s): ${ctx.projects.split(',').join(', ')}`,
  `Original steps: ${pass ? 'pass' : 'fail'}`,
  `Repeat runs: --repeat-each=${ctx.repeat_each} across ${ctx.projects.split(',').length} engines — ${pass ? 'all passed' : 'at least one failed'}`,
  `Regression (${ctx.grep}): ${pass ? 'passed' : 'failed'}`,
  `Regression test added: ${ctx.plan.regression_test_exists ? (ctx.plan.regression_test_hint || 'existing test') : 'NONE — add one tagged @regression ' + ctx.grep + ' with the bug ID in the title'}`,
  `Evidence: ${ctx.run_url || 'n/a'}`,
  '',
  pass ? 'Transitioning to Verified. A human QA must sign off and close — automation never closes tickets.' : 'Transitioning to Reopened with the evidence above; assigning back to development.',
].join('\n');
return [{ json: { ...ctx, verdict: pass ? 'PASS' : 'FAIL', target_statuses: pass ? ['Verified'] : ['Reopened', 'Reopen'], sheet_status: pass ? 'Verified' : 'Reopened', verified_date: pass ? today : '', comment } }];

const ctx = $('Verification Decision').last().json;
const transitions = $input.first().json.transitions || [];
const want = ctx.target_statuses.map((s) => s.toLowerCase());
const t = transitions.find((x) => want.includes(String(x.to?.name || '').toLowerCase()) || want.includes(String(x.name || '').toLowerCase()));
if (!t) throw new Error(`[Fix Verification] no transition to ${ctx.target_statuses.join('/')} available for ${ctx.bug.key} (have: ${transitions.map((x) => x.name + '→' + (x.to?.name || '?')).join(', ')})`);
if (/clos|done|resolv/i.test(String(t.to?.name || t.name))) throw new Error(`[Fix Verification] refusing transition "${t.name}" — automation never closes tickets`);
return [{ json: { ...ctx, transition_id: t.id, transition_name: t.name } }];
